python-collections.solution:
def word_counts(text):
    counts = {}
    for word in text.lower().split():
        counts[word] = counts.get(word, 0) + 1
    return counts

def top_student(scores):
    best = None
    for name, score in scores.items():
        if best is None or score > scores[best]:
            best = name
    return best
